import{_ as a,o as t,c as n,ag as s}from"./chunks/framework.BKVF-9lJ.js";const g=JSON.parse('{"title":"Agent operating model","description":"","frontmatter":{},"headers":[],"relativePath":"ai/agent-operating-model.md","filePath":"ai/agent-operating-model.md","lastUpdated":1790253757000}'),o={name:"ai/agent-operating-model.md"};function i(r,e,d,l,c,p){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="agent-operating-model" tabindex="-1">Agent operating model <a class="header-anchor" href="#agent-operating-model" aria-label="Permalink to &quot;Agent operating model&quot;">​</a></h1><p>MFE Forge uses three layers:</p><ol><li><strong>Agent OS:</strong> <code>AGENTS.md</code>, rules, skills, adapters, and handoff conventions.</li><li><strong>Project OS:</strong> manifest, config, discovery, diagnostics, sync, and migrations.</li><li><strong>Runtime OS:</strong> remote registry/loading, event bus, store, router, and health behavior.</li></ol><p>Agents should move through these layers deliberately. A runtime change may require a project contract or docs update; a CLI change should expose machine-readable state when agents need to inspect it.</p><h2 id="task-lifecycle" tabindex="-1">Task lifecycle <a class="header-anchor" href="#task-lifecycle" aria-label="Permalink to &quot;Task lifecycle&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>intake → discovery → design → implementation → verification → review → handoff</span></span></code></pre></div><p>Each phase has a stopping rule: discovery stops when affected files and contradictions are known; implementation stops when acceptance behavior exists; verification stops when relevant checks are classified; review stops when no unresolved high-severity finding remains.</p><h2 id="evidence-standard" tabindex="-1">Evidence standard <a class="header-anchor" href="#evidence-standard" aria-label="Permalink to &quot;Evidence standard&quot;">​</a></h2><p>A claim is supported by source, a test, command output, or an explicitly labeled assumption. “Looks correct” is not verification. External state such as GitHub CI is reported separately from local checks.</p><h2 id="handoff-standard" tabindex="-1">Handoff standard <a class="header-anchor" href="#handoff-standard" aria-label="Permalink to &quot;Handoff standard&quot;">​</a></h2><p>Every agent handoff reports outcome, changed areas, verification, risks/limitations, and next steps. Follow-up agents should receive the smallest useful context rather than a full transcript.</p>',11)])])}const m=a(o,[["render",i]]);export{g as __pageData,m as default};
